import numpy as np
def objs(g):
    g=np.array(g); m=g>0; seen=np.zeros_like(m); out=[]
    from collections import deque
    H,W=m.shape
    for i in range(H):
        for j in range(W):
            if m[i,j] and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=1; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=1; q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((min(ys),min(xs),max(ys),max(xs),g))
    return out
